// C++ - validate balanced parentheses using a stack
bool isValid(const string& s) {
    stack<char> st;
    unordered_map<char, char> match = {
        {')', '('},
        {']', '['},
        {'}', '{'}
    };

    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else {
            // c is a closing bracket
            if (st.empty() || st.top() != match[c]) {
                return false;
            }
            st.pop();
        }
    }

    return st.empty();
}

// C++ - remove all adjacent duplicate characters using a stack
string removeDuplicates(const string& s) {
    string st; // used as a stack via push_back and pop_back

    for (char c : s) {
        if (!st.empty() && st.back() == c) {
            st.pop_back(); // cancel the most recent character
        } else {
            st.push_back(c);
        }
    }

    return st;
}

// C++ - evaluate a postfix (Reverse Polish Notation) expression
int evalRPN(vector<string>& tokens) {
    stack<int> st;

    for (const string& tok : tokens) {
        if (tok == "+" || tok == "-" || tok == "*" || tok == "/") {
            int b = st.top(); st.pop(); // second operand, popped first
            int a = st.top(); st.pop(); // first operand, popped second

            if (tok == "+") st.push(a + b);
            else if (tok == "-") st.push(a - b);
            else if (tok == "*") st.push(a * b);
            else st.push(a / b);
        } else {
            st.push(stoi(tok));
        }
    }

    return st.top();
}

// C++ - evaluate an infix expression with +, -, *, / and no parentheses
int calculate(const string& s) {
    stack<int> st;
    int num = 0;
    char op = '+';

    for (int i = 0; i < (int)s.size(); i++) {
        char c = s[i];
        if (isdigit(c)) {
            num = num * 10 + (c - '0');
        }
        bool isLast = (i == (int)s.size() - 1);
        if ((!isspace(c) && !isdigit(c)) || isLast) {
            if (op == '+') st.push(num);
            else if (op == '-') st.push(-num);
            else if (op == '*') { int top = st.top(); st.pop(); st.push(top * num); }
            else if (op == '/') { int top = st.top(); st.pop(); st.push(top / num); }
            op = c;
            num = 0;
        }
    }

    int result = 0;
    while (!st.empty()) { result += st.top(); st.pop(); }
    return result;
}
